using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Documents;
using System.Windows.Markup;
using System.Windows.Media;
using Microsoft.Win32;

public class Desktop {
 YapiPane yapi; Window window; int mode; TextBox left,right; RichTextBox leftView,rightView; bool switched,syncing;
 readonly string[] savedLeft={"","",""},savedRight={"","",""};
 List<CompareLine> rendered;
 T Find<T>(string name) where T:class {return window.FindName(name) as T;}
 void Text(string name,string text){Find<TextBlock>(name).Text=text;}
 void Visible(string name,bool show){Find<UIElement>(name).Visibility=show?Visibility.Visible:Visibility.Collapsed;}
 void Hook(string name,Action action){Find<Button>(name).Click+=(s,e)=>{try{action();}catch(Exception ex){Text("Status","操作失败，请检查输入");MessageBox.Show(window,ex.Message,"请检查输入",MessageBoxButton.OK,MessageBoxImage.Warning);}};}
 public Desktop(){using(var stream=typeof(Desktop).Assembly.GetManifestResourceStream("Shell.xaml"))window=(Window)XamlReader.Load(stream);left=Find<TextBox>("LeftEditor");right=Find<TextBox>("RightEditor");leftView=Find<RichTextBox>("LeftHighlight");rightView=Find<RichTextBox>("RightHighlight");
 Hook("NavYapi",YapiPage);Hook("OpenYapi",YapiPage);Hook("NavHome",Home);Hook("NavFormat",()=>Page(0));Hook("OpenFormat",()=>Page(0));Hook("NavDiff",()=>Page(1));Hook("OpenDiff",()=>Page(1));Hook("NavText",()=>Page(2));Hook("OpenText",()=>Page(2));Hook("Run",()=>{if(mode>0)Compare();else Format(true);});Hook("Compress",()=>Format(false));Hook("Validate",()=>{Json.Parse(left.Text);Text("Status","✓ JSON 校验通过");});Hook("Clear",()=>{left.Clear();right.Clear();ResetResult();Text("Status","已清空");});Hook("Example",Example);Hook("Swap",()=>{string t=left.Text;left.Text=right.Text;right.Text=t;ResetResult();});Hook("LoadLeft",()=>Load(left));Hook("LoadRight",()=>Load(right));Hook("Copy",()=>{if(right.Text.Length>0){Clipboard.SetText(right.Text);Text("Status","已复制结果");}});Hook("Save",Save);Hook("EditInput",()=>{ShowHighlights(false);Text("Status","继续编辑后，点击比较差异重新生成高亮");});
 left.TextChanged+=(s,e)=>{Text("LeftCount",left.Text.Length.ToString("N0")+" 个字符");if(mode>0)ResetResult();};right.TextChanged+=(s,e)=>{Text("RightCount",right.Text.Length.ToString("N0")+" 个字符");if(mode>0)ResetResult();};
 leftView.AddHandler(ScrollViewer.ScrollChangedEvent,new ScrollChangedEventHandler((s,e)=>SyncScroll(leftView,rightView,e)));rightView.AddHandler(ScrollViewer.ScrollChangedEvent,new ScrollChangedEventHandler((s,e)=>SyncScroll(rightView,leftView,e)));Home();}
 void SyncScroll(RichTextBox source,RichTextBox target,ScrollChangedEventArgs e){if(syncing)return;if(e.VerticalChange==0&&e.HorizontalChange==0)return;syncing=true;try{target.ScrollToVerticalOffset(source.VerticalOffset);target.ScrollToHorizontalOffset(source.HorizontalOffset);}finally{syncing=false;}}
 void Persist(){if(!switched)return;savedLeft[mode]=left.Text;savedRight[mode]=right.Text;}
 void SelectNav(string name){foreach(string n in new[]{"NavHome","NavFormat","NavDiff","NavText","NavYapi"}){var b=Find<Button>(n);b.Background=BrushOf(n==name?"#303D64":"Transparent");b.Foreground=BrushOf(n==name?"#FFFFFF":"#ABB7CD");}}
 static Brush BrushOf(string color){return (Brush)new BrushConverter().ConvertFromString(color);}
 void YapiPage(){Persist();switched=false;if(yapi==null){yapi=new YapiPane();Find<Grid>("YapiHost").Children.Add(yapi.View);}Visible("HomePage",false);Visible("ToolPage",false);Visible("YapiHost",true);SelectNav("NavYapi");Text("Breadcrumb","工作空间 / 接口导入 YApi");}
 void Home(){Visible("YapiHost",false);Persist();switched=false;Visible("HomePage",true);Visible("ToolPage",false);SelectNav("NavHome");Text("Breadcrumb","工作空间  /  工具概览");Text("Status","就绪，选择一个工具开始");}
 void Page(int page){Visible("YapiHost",false);Persist();mode=page;switched=true;bool diff=mode>0;Visible("HomePage",false);Visible("ToolPage",true);SelectNav(mode==0?"NavFormat":mode==1?"NavDiff":"NavText");string title=mode==0?"JSON 格式化":mode==1?"JSON Diff":"文本比对";Text("Breadcrumb","工作空间  /  "+title);Text("ToolTitle",title);Text("ToolSubtitle",mode==0?"让数据更易读。格式化、压缩和校验，一步完成。":mode==1?"按 JSON 结构对齐，直接高亮每一处数据变化。":"逐行对齐文本，高亮新增、删除和行内修改。");Find<Button>("Run").Content=diff?"⇄  比较差异":"{ }  格式化";foreach(string n in new[]{"Compress","Validate","Copy","Save"})Visible(n,!diff);Visible("Swap",diff);Visible("LoadRight",diff);Visible("Results",false);Find<RowDefinition>("ResultSpacer").Height=new GridLength(0);Find<RowDefinition>("ResultRow").Height=new GridLength(0);right.IsReadOnly=!diff;Text("LeftTitle",mode==0?"输入 JSON":mode==1?"原始 JSON":"原始文本");Text("RightTitle",mode==0?"处理结果":mode==1?"新 JSON":"新文本");left.Text=savedLeft[mode];right.Text=savedRight[mode];ResetResult();Text("Status",mode==0?"粘贴 JSON 或打开文件，也可以先试试示例":mode==1?"忽略对象字段顺序 · 数组按索引比较 · 比较结果将自动排版":"按行比较 · 区分空格和大小写 · 忽略换行符类型（CRLF / LF）");}
 void ShowHighlights(bool show){Visible("LeftEditor",!show);Visible("RightEditor",!show);Visible("LeftHighlight",show);Visible("RightHighlight",show);Visible("EditInput",show);Visible("CompareLegend",show);}
 void ResetResult(){rendered=null;ShowHighlights(false);leftView.Document.Blocks.Clear();rightView.Document.Blocks.Clear();}
 void Load(TextBox box){var d=new OpenFileDialog{Filter="文本 / JSON|*.txt;*.json;*.log;*.csv;*.md;*.xml|所有文件|*.*"};if(d.ShowDialog(window)==true){box.Text=File.ReadAllText(d.FileName,Encoding.UTF8);ShowHighlights(false);Text("Status","已打开 "+System.IO.Path.GetFileName(d.FileName));}}
 void Save(){if(right.Text.Length==0)throw new Exception("请先生成处理结果");var d=new SaveFileDialog{Filter="JSON 文件|*.json",FileName="result.json"};if(d.ShowDialog(window)==true){File.WriteAllText(d.FileName,right.Text,new UTF8Encoding(false));Text("Status","已保存 "+System.IO.Path.GetFileName(d.FileName));}}
 void Format(bool pretty){var json=Json.Parse(left.Text);right.Text=json.Print(pretty);Text("Status",pretty?"✓ 格式化完成 · 两空格缩进":"✓ 压缩完成");}
 void Compare(){ResetResult();List<CompareLine> rows;string summary;bool coarse=false;
  if(mode==1){Json a,b;try{a=Json.Parse(left.Text);}catch(Exception ex){throw new Exception("原始 JSON："+ex.Message);}try{b=Json.Parse(right.Text);}catch(Exception ex){throw new Exception("新 JSON："+ex.Message);}var changes=new List<string[]>();Json.Diff(a,b,"$",changes);rows=Comparison.JsonLines(a,b);summary=changes.Count==0?"✓ 两份 JSON 内容一致":"共 "+changes.Count+" 处字段 / 结构变化";}
  else{rows=Comparison.TextLines(left.Text,right.Text,out coarse);int add=0,del=0,mod=0;foreach(var r in rows){if(r.Kind=="新增")add++;else if(r.Kind=="删除")del++;else if(r.Kind=="修改")mod++;}summary=add+del+mod==0?"✓ 两份文本内容一致":"新增 "+add+" 行 / 删除 "+del+" 行 / 修改 "+mod+" 行";}
  rendered=rows;Render(leftView,rows,true);Render(rightView,rows,false);ShowHighlights(true);Text("Status",summary+(coarse?" · 大范围差异采用区块对齐":"")+(mode==1?" · 悬停查看 JSON 路径":""));}
 void Render(RichTextBox view,List<CompareLine> rows,bool old){
  var doc=new FlowDocument{PagePadding=new Thickness(0),FontFamily=new FontFamily("Consolas, Microsoft YaHei UI"),FontSize=14,PageWidth=500};int number=0; double width=Math.Max(200,left.ActualWidth-28); foreach(var row in rows){string line=old?row.Left:row.Right;if(line!=null){var measure=new FormattedText(line,System.Globalization.CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Consolas, Microsoft YaHei UI"),14,Brushes.Black,VisualTreeHelper.GetDpi(view).PixelsPerDip);width=Math.Max(width,measure.WidthIncludingTrailingWhitespace+100);}}doc.PageWidth=width;
  foreach(var row in rows){string value=old?row.Left:row.Right;bool changed=row.Kind!="相同";string color=value==null?"#F3F5F9":!changed?"#FFFFFF":row.Kind=="修改"?"#FFF5D5":old?"#FDE8EC":"#E0F5E9";
   var p=new Paragraph{Margin=new Thickness(0),Padding=new Thickness(4,2,4,2),LineHeight=23,LineStackingStrategy=LineStackingStrategy.BlockLineHeight,Background=BrushOf(color),ToolTip=row.Path.Length>0?row.Path:row.Kind};
   string label=value==null?"":(++number).ToString();p.Inlines.Add(new Run(label.PadLeft(5)+"  "){Foreground=BrushOf("#9AA6BA"),FontSize=11});
   if(value==null)p.Inlines.Add(new Run(" "));else if(row.Kind=="修改"&&row.Left!=null&&row.Right!=null){int prefix=0,suffix=0;while(prefix<row.Left.Length&&prefix<row.Right.Length&&row.Left[prefix]==row.Right[prefix])prefix++;while(suffix<row.Left.Length-prefix&&suffix<row.Right.Length-prefix&&row.Left[row.Left.Length-1-suffix]==row.Right[row.Right.Length-1-suffix])suffix++;p.Inlines.Add(new Run(value.Substring(0,prefix)));p.Inlines.Add(new Run(value.Substring(prefix,value.Length-prefix-suffix)){Background=BrushOf(old?"#F8C5CF":"#AFE5C6"),FontWeight=FontWeights.SemiBold});p.Inlines.Add(new Run(value.Substring(value.Length-suffix)));}
   else p.Inlines.Add(new Run(value));doc.Blocks.Add(p);
  }view.Document=doc;view.ScrollToHome();
 }
 void Example(){if(mode==2){left.Text="个人工具箱\n版本：1.1\n功能：JSON 格式化\n功能：JSON Diff\n旧说明：仅支持 JSON\n完成";right.Text="个人工具箱\n版本：1.2\n功能：JSON 格式化\n功能：JSON Diff\n功能：文本比对\n新增说明：支持高亮\n完成";}else{left.Text=Json.Parse("{\"name\":\"MyTool\",\"version\":\"1.1\",\"tools\":[\"JSON Formatter\",\"JSON Diff\"],\"local\":true}").Print(true);if(mode==1)right.Text=Json.Parse("{\"name\":\"MyTool\",\"version\":\"1.2\",\"tools\":[\"JSON Formatter\",\"JSON Diff\",\"Text Diff\"],\"theme\":\"light\"}").Print(true);else Format(true);}Text("Status","示例已载入，可直接编辑和处理");}
 [STAThread]public static int Main(string[] args){if(args.Length==2&&args[0]=="--upload-check"){try{var profiles=YapiCache.Load();var profile=profiles.First();var entry=new JavaScanner(profile.SourceRoot).Scan(profile.ScanDirectory).Single(a=>a.Key==args[1]);if(entry.Warning.Length>0)throw new Exception("Selected endpoint has diagnostics");var client=new YapiClient(profile);string outcome=client.Upload(entry,profile,client.Existing(profile.ProjectId));profile.LastUpload=DateTime.Now.ToString("yyyy-MM-dd HH:mm");profile.LastResult=outcome+"（单接口验证）";if(!profile.SelectedKeys.Contains(entry.Key))profile.SelectedKeys.Add(entry.Key);YapiCache.Save(profiles);File.WriteAllText("upload-check.txt",entry.Key+" "+outcome);return 0;}catch(Exception ex){File.WriteAllText("upload-check.txt",ex.Message);return 1;}}if(args.Length==4&&args[0]=="--configure-yapi"){var profiles=YapiCache.Load();var profile=profiles.FirstOrDefault(p=>p.Server==args[1]&&p.ScanDirectory==args[3])??new YapiProfile();profile.Server=args[1];profile.SourceRoot=args[2];profile.ScanDirectory=args[3];profile.SetToken(Environment.GetEnvironmentVariable("MYTOOL_YAPI_TOKEN")??"");var client=new YapiClient(profile);var project=client.Project();profile.ProjectId=Convert.ToInt32(project["_id"]);profile.ProjectName=Convert.ToString(project["name"]);profile.Name=profile.ProjectName;var cats=client.Categories(profile.ProjectId);if(profile.CategoryId==0&&cats.Count>0)profile.CategoryId=cats[0].Id;if(!profiles.Any(p=>p.Id==profile.Id))profiles.Add(profile);YapiCache.Save(profiles);return 0;}if(args.Length==3&&args[0]=="--scan-check"){try{var apis=new JavaScanner(args[1]).Scan(args[2]);File.WriteAllText("scan-preview.json",JavaScanner.Serializer().Serialize(apis.Select(a=>new {a.Path,a.Warning,a.Payload}).ToList()));File.WriteAllText("scan-check.txt",string.Join(Environment.NewLine,apis.Select(a=>a.Method+" "+a.Path+" | "+a.Warning).ToArray()));return 0;}catch(Exception ex){File.WriteAllText("scan-check.txt",ex.ToString());return 1;}}if(args.Length>0&&args[0]=="--self-test"){int result=Tests.Run();if(result!=0)return result;try{ComparisonTests.Run();ImporterTests.Run();var test=new Desktop();test.Page(0);test.Example();if(Json.Parse(test.left.Text).Print(false)!=Json.Parse(test.right.Text).Print(false))throw new Exception("Format UI failed");test.Page(1);test.Example();test.Compare();if(test.rendered==null||test.leftView.Document.Blocks.Count!=test.rightView.Document.Blocks.Count)throw new Exception("Highlight UI failed");test.Page(2);test.Example();test.Compare();if(test.rendered.FindAll(r=>r.Kind!="相同").Count==0)throw new Exception("Text UI failed");test.Page(0);if(test.left.Text.Length==0)throw new Exception("Page persistence failed");test.window.Close();File.AppendAllText("test-results.txt",Environment.NewLine+"PASS: text alignment, JSON structural highlights, WPF views, page persistence.");return 0;}catch(Exception ex){File.AppendAllText("test-results.txt",Environment.NewLine+"FAIL: "+ex);return 1;}}var app=new Application();var desktop=new Desktop();app.Run(desktop.window);return 0;}
}

public static class ComparisonTests {
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 static string Rebuild(List<CompareLine> rows,bool left){var lines=new List<string>();foreach(var r in rows){string s=left?r.Left:r.Right;if(s!=null)lines.Add(s);}return string.Join("\n",lines.ToArray());}
 public static void Run(){bool coarse;var rows=Comparison.TextLines("a\nb\nc","a\nx\nb\nc",out coarse);Check(rows.Count==4&&rows[1].Kind=="新增"&&rows[2].Kind=="相同","Insertion alignment");
  rows=Comparison.TextLines("a\nb\nc","a\nc",out coarse);Check(rows[1].Kind=="删除"&&rows[2].Left=="c","Deletion alignment");
  foreach(var pair in new[]{new[]{"",""},new[]{"\n",""},new[]{" a\nB","a\nb\n"},new[]{"a\na\nb","a\nb\na"},new[]{"a\r\nb\r","a\nb\n"}}){rows=Comparison.TextLines(pair[0],pair[1],out coarse);Check(Rebuild(rows,true)==pair[0].Replace("\r\n","\n").Replace('\r','\n'),"Left reconstruction");Check(Rebuild(rows,false)==pair[1].Replace("\r\n","\n").Replace('\r','\n'),"Right reconstruction");}
  var a=Json.Parse("{\"a\":1,\"b\":[1,{\"c\":true}],\"gone\":{\"x\":2}}");var b=Json.Parse("{\"b\":[1,{\"c\":false},3],\"a\":1,\"new\":[]}");rows=Comparison.JsonLines(a,b);Check(Json.Parse(Rebuild(rows,true)).Print(false)==a.Print(false),"JSON left reconstruction");var differences=new List<string[]>();Json.Diff(Json.Parse(Rebuild(rows,false)),b,"$",differences);Check(differences.Count==0,"JSON right reconstruction");Check(rows.Exists(r=>r.Kind=="修改"&&r.Path=="$[\"b\"][1][\"c\"]"),"Nested JSON highlight");rows=Comparison.JsonLines(Json.Parse("{\"a\":1,\"b\":2}"),Json.Parse("{\"b\":2,\"a\":1}"));Check(!rows.Exists(r=>r.Kind!="相同"),"Key ordering ignored");
  foreach(var pair in new[]{new[]{"{}","{\"a\":1}"},new[]{"[1]","[]"},new[]{"1","{\"x\":[true]}"},new[]{"null","false"}}){rows=Comparison.JsonLines(Json.Parse(pair[0]),Json.Parse(pair[1]));Check(Json.Parse(Rebuild(rows,true)).Print(false)==Json.Parse(pair[0]).Print(false),"JSON type left");Check(Json.Parse(Rebuild(rows,false)).Print(false)==Json.Parse(pair[1]).Print(false),"JSON type right");}
  var manyA=new string[1500];var manyB=new string[1500];for(int i=0;i<1500;i++){manyA[i]="a"+i;manyB[i]="b"+i;}rows=Comparison.TextLines(string.Join("\n",manyA),string.Join("\n",manyB),out coarse);Check(coarse&&rows.Count==1500,"Bounded large diff");
 }
}







